            if(used==bytes.length){digest.update(bytes);used=0;}
        }
        if(used>0)digest.update(bytes,0,used);return digest.digest();
    }
    private void scheduler(String message){if(context!=null)AppDiagnostics.log(context,"INFO","native-scheduler",message);}

    /** Only a Run rejection is optional; tensor/session construction and retirement still fail normally. */
    private OrtSession.Result execute(OrtSession session,OnnxTensor input,OnnxTensor output,NativeDeuxTransform.Check check)throws Exception{
        try{return session.run(Collections.singletonMap("input",input),Collections.emptySet(),Collections.singletonMap("output",output),activeRun);}
        catch(OrtException rejected){
            // Normalize only a native Run failure with confirmed caller cancellation.
            // Resource construction/close remain outside this catch. An annotated
            // failure may already carry unknown cleanup errors and stays unchanged.
            if(rejected.getCause()!=null||rejected.getSuppressed().length!=0)throw rejected;
            try{check.check();}
            catch(InterruptedIOException stopped){stopped.initCause(rejected);throw stopped;}
            catch(ProbeAborted budget){/* A probe deadline cannot hide the actual Run failure. */}
            if(probing)throw new ProbeRunRejected(rejected);
            throw rejected;
        }
    }

    private void run(OrtSession session,FloatBuffer input,long[] inputShape,FloatBuffer output,long[] outputShape,NativeDeuxTransform.Check check,NativeInferenceProfile profile) throws Exception {
        check.check();
        boolean first=firstGraphRun;if(first)phase("session-run-start; graph="+activeGraph);
        NativeInferenceProfile.Timing bindStarted=profile==null?null:NativeInferenceProfile.started();boolean bound=false;
        try(OnnxTensor x=OnnxTensor.createTensor(OrtEnvironment.getEnvironment(),input,inputShape);
            OnnxTensor y=OnnxTensor.createTensor(OrtEnvironment.getEnvironment(),output,outputShape)) {
            if(profile!=null){profile.addTensorBind(activeGraph,NativeInferenceProfile.elapsed(bindStarted));bound=true;}
            NativeInferenceProfile.Timing runStarted=profile==null?null:NativeInferenceProfile.started();
            try(OrtSession.Result result=execute(session,x,y,check)) {
                if(first){firstGraphRun=false;phase("session-run-complete; graph="+activeGraph);}
                check.check();
            }finally{if(profile!=null)profile.addRun(activeGraph,NativeInferenceProfile.elapsed(runStarted));}
        }finally{if(profile!=null&&!bound)profile.addTensorBind(activeGraph,NativeInferenceProfile.elapsed(bindStarted));}
    }

    /** Flush only at graph boundaries so a native process death retains its last phase. */
    private void phase(String detail) {
        if(context!=null){AppDiagnostics.log(context,"INFO","native-phase",detail+"; role="+(probing?"probe":"production"));AppDiagnostics.flush(1000);}
    }

    private File model(String name,NativeDeuxTransform.Check check) throws Exception {
        JSONObject entry=validateEntry(name);String filename=name+".onnx";File model=new File(modelDirectory,filename);
        if(verified.contains(filename)&&model.isFile()&&model.length()==entry.getLong("bytes"))return model;
        if(model.isFile()&&model.length()==entry.getLong("bytes")&&entry.getString("sha256").equals(modelFileDigest(model,check))) {
            verified.add(filename);return model;
        }
        if(context==null)throw new IOException("The studio model checksum does not match: "+filename);
        if(modelDirectory.getUsableSpace()<entry.getLong("bytes")+32L*1024*1024)throw new IOException("Studio analysis needs more free storage to prepare its offline models.");
        File partial=File.createTempFile(".model-",".partial",modelDirectory);
        try {
            MessageDigest hash=MessageDigest.getInstance("SHA-256");long bytes=0;
            modelExtractionAttempts++;
            try(InputStream in=context.getAssets().open(ASSET_ROOT+filename);FileOutputStream out=new FileOutputStream(partial)) {
                byte[] buffer=new byte[262144];int count;
                while((count=in.read(buffer))!=-1) {
                    modelExtractionBytesRead+=count;
                    check.check();bytes+=count;if(bytes>entry.getLong("bytes"))throw new IOException("The studio model is too large.");
                    out.write(buffer,0,count);hash.update(buffer,0,count);
                }
                out.getFD().sync();
            }
            if(bytes!=entry.getLong("bytes")||!entry.getString("sha256").equals(hex(hash.digest())))throw new IOException("The studio model is damaged: "+filename);
            check.check();Files.move(partial.toPath(),model.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
            verified.add(filename);return model;
        }finally{partial.delete();}
    }

    /** Prepare every graph before timed comparisons so neither arm pays one-time extraction. */
    private void preflightCache(NativeDeuxTransform.Check check,NativeInferenceProfile profile) throws Exception {
        List<String> names=new ArrayList<>(Arrays.asList("front","head-0","head-1"));
        for(int i=0;i<12;i++){names.add(blockName(i)+"-time");names.add(blockName(i)+"-frequency");}
        List<String> missingNames=new ArrayList<>();
        long missing=0,largest=0;
        for(String name:names) {
            check.check();JSONObject entry=validateEntry(name);String filename=name+".onnx";File file=new File(modelDirectory,filename);
            long bytes=entry.getLong("bytes");boolean intact=false;
            if(file.isFile()&&file.length()==bytes)intact=verified.contains(filename)||entry.getString("sha256").equals(modelFileDigest(file,check));
            if(intact){
                verified.add(filename);
                if(profile!=null)profile.noteCacheModelHit(bytes);
            }
            else {
                verified.remove(filename);
                if(profile!=null)profile.noteCacheModelMiss(bytes);
                if(context==null)throw new IOException("The studio model checksum does not match: "+filename);
                missingNames.add(name);
                missing+=bytes;largest=Math.max(largest,bytes);
            }
        }
        if(context!=null) {
            // Reserve a full head-sized atomic replacement plus checkpoint/output space.
            long needed=missing+largest+32L*1024*1024,available=modelDirectory.getUsableSpace();
            if(available<needed) {
                long mib=1024*1024;
                throw new IOException("Studio analysis needs "+((needed+mib-1)/mib)+" MB of free storage ("+(available/mib)+" MB available). Free "+((needed-available+mib-1)/mib)+" MB and retry.");
            }
        }
        // The caller's common preflight timer owns extraction and checksum cost.
        // Per-graph preparation subsequently looks up the already verified files.
        for(String name:missingNames){check.check();model(name,check);}
    }

    private JSONObject validateEntry(String name) throws Exception {
        if(!name.matches("(?:front|head-[01]|block-(?:0[0-9]|1[01])-(?:time|frequency))"))throw new IOException("Invalid studio model name.");
        JSONObject entry=files.getJSONObject(name+".onnx");long bytes=entry.getLong("bytes");
        if(bytes<1 || bytes>1024L*1024*1024 || !entry.getString("sha256").matches("[0-9a-f]{64}"))throw new IOException("The studio model inventory is invalid.");
        return entry;
    }
    private static int[] integers(JSONArray array,int size,int min,int max) throws Exception {
        if(array.length()!=size)throw new IOException("Invalid studio frequency geometry.");int[] values=new int[size];
        for(int i=0;i<size;i++){values[i]=array.getInt(i);if(values[i]<min||values[i]>max)throw new IOException("Invalid studio frequency index.");}return values;
    }
    private static String blockName(int index){return "block-"+(index<10?"0":"")+index;}
    private static void progress(Listener listener,double progress,String message){if(listener!=null)listener.update(progress,message);}
    private static FloatBuffer direct(int count){return ByteBuffer.allocateDirect(Math.multiplyExact(count,4)).order(ByteOrder.nativeOrder()).asFloatBuffer();}
    private static FloatBuffer slice(FloatBuffer buffer,int offset,int count){FloatBuffer part=buffer.duplicate();part.position(offset);part.limit(offset+count);return part.slice();}
    private static void copy(FloatBuffer from,int source,FloatBuffer to,int target,int count){FloatBuffer src=from.duplicate(),dst=to.duplicate();src.position(source);src.limit(source+count);dst.position(target);dst.put(src);}
    private static byte[] readBounded(InputStream in,int max) throws IOException {
        ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;
        while((count=in.read(buffer))!=-1){if(out.size()+count>max)throw new IOException("The studio manifest is too large.");out.write(buffer,0,count);}return out.toByteArray();
    }
    private static String digest(File file,NativeDeuxTransform.Check check) throws Exception {
        MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] buffer=new byte[262144];int count;
            while((count=in.read(buffer))!=-1){check.check();hash.update(buffer,0,count);}}return hex(hash.digest());
    }
    private String modelFileDigest(File file,NativeDeuxTransform.Check check)throws Exception{
        modelChecksumAttempts++;
        MessageDigest hash=MessageDigest.getInstance("SHA-256");
        try(InputStream in=new FileInputStream(file)){byte[] buffer=new byte[262144];int count;
            while((count=in.read(buffer))!=-1){modelChecksumBytesRead+=count;check.check();hash.update(buffer,0,count);}}
        return hex(hash.digest());
    }
    private static String hex(byte[] bytes){StringBuilder text=new StringBuilder(bytes.length*2);for(byte b:bytes)text.append(Character.forDigit((b>>>4)&15,16)).append(Character.forDigit(b&15,16));return text.toString();}
    private static void writeFloats(OutputStream out,float[] pcm,NativeDeuxTransform.Check check) throws IOException {
        ByteBuffer block=ByteBuffer.allocate(32768).order(ByteOrder.LITTLE_ENDIAN);
        for(int first=0;first<pcm.length;) {
            check.check();int count=Math.min(block.capacity()/4,pcm.length-first);block.clear();
            for(int i=0;i<count;i++){float value=pcm[first+i];if(!Float.isFinite(value))throw new IOException("The studio result contains invalid audio.");block.putFloat(value);}
            out.write(block.array(),0,count*4);first+=count;
        }
    }
}

package com.cyberbasslord.lightforge;

import java.io.*;
import java.nio.*;
import java.util.Arrays;

/** Source-clock-identical port of separator-deux.js. No Android or ONNX dependency. */
final class NativeDeuxTransform {
    static final int RATE=44100, NFFT=2048, HOP=441, FRAMES=1301, SAMPLES=573300;
    static final int SPECTRUM_FLOATS=2050*FRAMES*2;
    interface Check { void check() throws IOException; }
    private final double[] re=new double[NFFT], im=new double[NFFT], window=new double[NFFT];
    private final double[] norm=new double[SAMPLES+NFFT];
    private final FFT fft=new FFT(NFFT);

    NativeDeuxTransform() {
        for(int i=0;i<NFFT;i++)window[i]=.5-.5*Math.cos(2*Math.PI*i/NFFT);
        for(int f=0;f<FRAMES;f++)for(int i=0;i<NFFT;i++)norm[f*HOP+i]+=window[i]*window[i];
    }

    /** PCM16 stereo WAVE, including RIFF ancillary chunks; absent source samples are zero. */
    static float[][] readStereo(File file,long startSample,Check check) throws IOException {
        if(startSample < -SAMPLES || startSample > RATE*14401L)throw new IOException("Invalid studio passage position.");
        float[][] result=new float[2][SAMPLES];
        try(RandomAccessFile in=new RandomAccessFile(file,"r")) {
            if(in.length()<44 || in.readInt()!=0x52494646)throw new IOException("Studio analysis requires a PCM WAVE source.");
            long riffEnd=8+u32(in);
            if(in.readInt()!=0x57415645 || riffEnd>in.length() || riffEnd<44)throw new IOException("The source WAVE header is invalid.");
            boolean format=false;long offset=-1,bytes=0;
            while(in.getFilePointer()+8<=riffEnd) {
                check.check();int id=in.readInt();long size=u32(in),begin=in.getFilePointer();
                if(size>riffEnd-begin)throw new IOException("The source WAVE is truncated.");
                if(id==0x666d7420) {
                    if(size<16 || u16(in)!=1 || u16(in)!=2 || u32(in)!=RATE || u32(in)!=RATE*4L || u16(in)!=4 || u16(in)!=16)
                        throw new IOException("Studio analysis requires 44,100 Hz, 16-bit stereo PCM.");
                    format=true;
                } else if(id==0x64617461 && offset<0) {offset=begin;bytes=size;}
                long next=begin+size+(size&1);
                if(next>riffEnd)throw new IOException("The source WAVE chunk padding is invalid.");
                in.seek(next);
            }
            if(!format || offset<0 || bytes%4!=0)throw new IOException("The source WAVE has no valid stereo audio.");
            long first=Math.max(0,startSample),last=Math.min(bytes/4,startSample+SAMPLES);
            if(last<=first)return result;
            in.seek(offset+first*4);byte[] buffer=new byte[32768];
            while(first<last) {
                check.check();int count=(int)Math.min(buffer.length/4,last-first);in.readFully(buffer,0,count*4);
                int dst=(int)(first-startSample);
                for(int i=0;i<count;i++)for(int c=0;c<2;c++) {
                    int at=i*4+c*2;short value=(short)((buffer[at]&255)|((buffer[at+1]&255)<<8));
                    result[c][dst+i]=value/32768f;
                }
                first+=count;
            }
        }
        return result;
    }

    void encode(float[][] stereo,FloatBuffer spectrum,Check check) throws IOException {
        if(stereo.length!=2 || stereo[0].length!=SAMPLES || stereo[1].length!=SAMPLES || spectrum.capacity()!=SPECTRUM_FLOATS)
            throw new IOException("Studio separation requires a complete stereo passage.");
        for(int c=0;c<2;c++)for(int f=0;f<FRAMES;f++) {
            if((f&31)==0)check.check();int start=f*HOP-NFFT/2;
            for(int i=0;i<NFFT;i++) {
                int at=start+i;if(at<0)at=-at;if(at>=SAMPLES)at=2*SAMPLES-at-2;
                float value=stereo[c][at];if(!Float.isFinite(value))throw new IOException("Invalid studio source audio.");
                re[i]=value*window[i];im[i]=0;
            }
            fft.run(re,im,false);
            for(int b=0;b<=NFFT/2;b++) {int at=((b*2+c)*FRAMES+f)*2;spectrum.put(at,(float)re[b]);spectrum.put(at+1,(float)im[b]);}
        }
    }

    float[] decode(FloatBuffer spectrum,FloatBuffer mask,int[] indices,int[] bandsPerFrequency,FloatBuffer summed,Check check) throws IOException {
        if(mask.capacity()!=indices.length*FRAMES*2 || spectrum.capacity()!=SPECTRUM_FLOATS || summed.capacity()!=SPECTRUM_FLOATS)
            throw new IOException("Studio separator returned an invalid mask.");
        for(int i=0;i<summed.capacity();i++)summed.put(i,0);
        // Deliberately round after every addition, matching Float32Array accumulation.
        for(int j=0;j<indices.length;j++) {
            if((j&63)==0)check.check();int dst=indices[j]*FRAMES*2,src=j*FRAMES*2;
            for(int i=0;i<FRAMES*2;i++)summed.put(dst+i,summed.get(dst+i)+mask.get(src+i));
        }
        float[] pcm=new float[SAMPLES+NFFT];
        for(int c=0;c<2;c++)for(int f=0;f<FRAMES;f++) {
            if((f&31)==0)check.check();Arrays.fill(re,0);Arrays.fill(im,0);
            for(int b=0;b<=NFFT/2;b++) {
                int at=((b*2+c)*FRAMES+f)*2;double d=Math.max(1e-8,bandsPerFrequency[b]);
                double ar=spectrum.get(at),ai=spectrum.get(at+1),mr=summed.get(at)/d,mi=summed.get(at+1)/d;
                double r=ar*mr-ai*mi,v=ar*mi+ai*mr;
                if(!Double.isFinite(r)||!Double.isFinite(v))throw new IOException("Studio separation produced invalid audio.");
                re[b]=r;im[b]=v;if(b>0&&b<NFFT/2){re[NFFT-b]=r;im[NFFT-b]=-v;}
            }
            fft.run(re,im,true);
            for(int i=0;i<NFFT;i++)pcm[f*HOP+i]=(float)(pcm[f*HOP+i]+re[i]*window[i]*.5);
        }
        float[] out=new float[SAMPLES];
        for(int i=0;i<SAMPLES;i++)out[i]=(float)(pcm[i+NFFT/2]/Math.max(1e-12,norm[i+NFFT/2]));
        return out;
    }

    private static int u16(RandomAccessFile in) throws IOException {int a=in.readUnsignedByte();return a|in.readUnsignedByte()<<8;}
    private static long u32(RandomAccessFile in) throws IOException {return (long)u16(in)|((long)u16(in)<<16);}
    private static final class FFT {
        final int n;final int[] rev;final double[] cos,sin;
        FFT(int n) {
            this.n=n;rev=new int[n];cos=new double[n/2];sin=new double[n/2];int bits=Integer.numberOfTrailingZeros(n);
            for(int i=0;i<n;i++)rev[i]=Integer.reverse(i) >>> (32-bits);
            for(int i=0;i<n/2;i++){cos[i]=Math.cos(2*Math.PI*i/n);sin[i]=Math.sin(2*Math.PI*i/n);}
        }
        void run(double[] r,double[] im,boolean inverse) {
            for(int i=0;i<n;i++){int j=rev[i];if(i<j){double t=r[i];r[i]=r[j];r[j]=t;t=im[i];im[i]=im[j];im[j]=t;}}
            for(int len=2;len<=n;len*=2){int half=len/2,step=n/len;
                for(int start=0;start<n;start+=len)for(int j=0;j<half;j++){
                    int k=j*step,a=start+j,b=a+half;double c=cos[k],s=sin[k]*(inverse?1:-1),tr=r[b]*c-im[b]*s,ti=r[b]*s+im[b]*c;
                    r[b]=r[a]-tr;im[b]=im[a]-ti;r[a]+=tr;im[a]+=ti;
                }
            }
            if(inverse)for(int i=0;i<n;i++){r[i]/=n;im[i]/=n;}
        }
    }
}

package com.cyberbasslord.lightforge;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.zip.CRC32;

/** Bounded CPU scheduling decisions. This class never runs inference or handles model tensors. */
final class NativeExecutionPolicy {
    static final int MIN_PAIRS=3, MAX_PAIRS=8, MAX_BYTES=8192, TEMPORAL_BANDS=60;
    // The caller subtracts its app reserve and the platform low-memory threshold first.
    static final long FOUR_WORKER_HEADROOM=1536L*1024*1024, EIGHT_WORKER_HEADROOM=2048L*1024*1024;
    private static final int MAGIC=0x4c465031, SCHEMA=2;
    private static final long MAX_TRIAL_NANOS=3600000000000L;
    private NativeExecutionPolicy() {}

    static final class Config {
        final int intraThreads,interThreads,dynamicBlockBase,temporalWorkers,timeBatch;
        final boolean parallel;
        private Config(int intra,int inter,int block,boolean parallel,int workers,int batch){
            intraThreads=intra;interThreads=inter;dynamicBlockBase=block;this.parallel=parallel;temporalWorkers=workers;timeBatch=batch;
        }
        @Override public boolean equals(Object other){
            if(!(other instanceof Config))return false;Config c=(Config)other;
            return intraThreads==c.intraThreads&&interThreads==c.interThreads&&dynamicBlockBase==c.dynamicBlockBase&&parallel==c.parallel&&temporalWorkers==c.temporalWorkers&&timeBatch==c.timeBatch;
        }
        @Override public int hashCode(){return ((((intraThreads*31+interThreads)*31+dynamicBlockBase)*31+(parallel?1:0))*31+temporalWorkers)*31+timeBatch;}
        String id(){return "cpu-i"+intraThreads+"-j"+interThreads+"-d"+dynamicBlockBase+(parallel?"-parallel":"-sequential")+(temporalWorkers==1?"":"-w"+temporalWorkers+"-b"+timeBatch);}
    }
    static Config baseline(int cores){return new Config(Math.max(1,Math.min(4,cores)),1,0,false,1,4);}
    static Config[] candidates(int cores){
        Config four=new Config(baseline(cores).intraThreads,1,4,false,1,4),two=new Config(Math.max(1,Math.min(2,cores)),1,4,false,1,4);
        if(cores>=6)return new Config[]{four,two,new Config(6,1,4,false,1,4)};
        return four.equals(two)?new Config[]{four}:new Config[]{four,two};
    }
    private static Config temporalConfig(int workers){return new Config(1,1,0,false,workers,1);}
    /** Frequency companion to a complete-passage candidate; never independent admission. */
    static Config parallelFrequency(int workers){
        if(workers!=4&&workers!=8)throw new IllegalArgumentException("Unsupported frequency worker count.");
        return new Config(1,1,0,false,workers,16);
    }
    /** Include every geometry allowed by the observed free-memory snapshot, in stable order. */
    static Config[] temporalCandidates(Key key,long availableBytes){
        if(key.cores<4||availableBytes<FOUR_WORKER_HEADROOM)return new Config[0];
        if(key.cores>=8&&availableBytes>=EIGHT_WORKER_HEADROOM)return new Config[]{temporalConfig(4),temporalConfig(8)};
        return new Config[]{temporalConfig(4)};
    }
    /** Cached candidates still require a fresh memory check before every graph. */
    static boolean temporalAllowed(Config config,Key key,long availableBytes){
        return baseline(key.cores).equals(config)||index(temporalCandidates(key,availableBytes),config)>=0;
    }
    /** A memory-limited cache remains safe, but must be expanded when a new geometry becomes affordable. */
    static boolean temporalNeedsExpansion(Decision decision,Key key,long availableBytes){
        if(decision==null||!decision.complete||!decision.temporalFamily||key.cores<4)return false;
        for(Config allowed:temporalCandidates(key,availableBytes)){
            boolean measured=false;
            if(decision.trials!=null)for(Candidate trial:decision.trials)if(allowed.equals(trial.config)){measured=true;break;}
            if(!measured)return true;
        }
        return false;
    }
    /** Identity is retained only as a digest; no raw device, OS, model or runtime string is saved. */
    static final class Key {
        final int cores;
        private final byte[] fingerprint;
        String identity(){StringBuilder value=new StringBuilder(64);for(byte b:fingerprint)value.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return value.toString();}
        Key(String modelId,String runtimeId,String osIdentity,String deviceIdentity,int cores){
            this.cores=Math.max(1,cores);
            try{
                ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);
                out.writeInt(SCHEMA);out.writeInt(this.cores);
                for(String value:new String[]{modelId,runtimeId,osIdentity,deviceIdentity}){
                    if(value==null||value.isEmpty()||value.length()>4096)throw new IllegalArgumentException("Missing or oversized execution identity.");
                    byte[] encoded=value.getBytes(StandardCharsets.UTF_8);out.writeInt(encoded.length);out.write(encoded);
                }
                out.flush();fingerprint=MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray());
            }catch(IOException|java.security.NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}
        }
    }
    static final class Sample {
        final long baselineNanos,candidateNanos;
        final boolean candidateFirst,finite,exact;
        final int temporalBands;
        Sample(long baselineNanos,long candidateNanos,boolean candidateFirst,boolean finite,boolean exact){this(baselineNanos,candidateNanos,candidateFirst,finite,exact,0);}
        Sample(long baselineNanos,long candidateNanos,boolean candidateFirst,boolean finite,boolean exact,int temporalBands){
            this.baselineNanos=baselineNanos;this.candidateNanos=candidateNanos;this.candidateFirst=candidateFirst;this.finite=finite;this.exact=exact;this.temporalBands=temporalBands;
        }
    }
    static final class Candidate {
        final Config config;
        private final Sample[] samples;
        Candidate(Config config,Sample[] samples){this.config=config;this.samples=samples==null?null:samples.clone();}
    }
    static final class Decision {
        final Config config;
        final boolean complete,eligible;
        final int pairCount;
        final long baselineMedianNanos,candidateMedianNanos;
        final String reason;
        private final boolean temporalFamily;
        private final long availableBytes;
        private final Candidate[] trials;
        private Decision(Config config,boolean complete,boolean eligible,int pairs,long baseline,long candidate,String reason,boolean temporal,long availableBytes,Candidate[] trials){
            this.config=config;this.complete=complete;this.eligible=eligible;pairCount=pairs;baselineMedianNanos=baseline;candidateMedianNanos=candidate;this.reason=reason;
            temporalFamily=temporal;this.availableBytes=availableBytes;this.trials=trials==null?null:trials.clone();
        }
    }
    static final class Calibration {
        final Decision temporal,frequency;
        Calibration(Decision temporal,Decision frequency){if(temporal==null||frequency==null)throw new IllegalArgumentException("Missing family decision.");this.temporal=temporal;this.frequency=frequency;}
        boolean complete(){return temporal.complete&&frequency.complete;}
    }
    static Calibration defaults(Key key){return new Calibration(unmeasured(key.cores,true),unmeasured(key.cores,false));}
    private static Decision unmeasured(int cores,boolean temporal){return new Decision(baseline(cores),false,false,0,0,0,"unmeasured",temporal,0,null);}
    /** Only immutable CPU incapability is cacheable without trials; temporary low memory is not. */
    static Decision retainedTemporal(Key key){
        return key.cores<4?new Decision(baseline(key.cores),true,false,0,0,0,"insufficient-cores",true,0,new Candidate[0]):unmeasured(key.cores,true);
    }

    /** Existing frequency shortlist: all configurations need complete alternating trials. */
    static Decision select(Key key,Candidate[] trials){return selectFrom(key,candidates(key.cores),trials,false,0);}
    /** Memory is part of shortlist evidence, so callers cannot silently omit an eligible candidate. */
    static Decision selectTemporal(Key key,long availableBytes,Config[] shortlist,Candidate[] trials){
        Config[] allowed=temporalCandidates(key,availableBytes);
        if(allowed.length==0||!sameSet(allowed,shortlist))return retainedTemporal(key);
        return selectFrom(key,allowed,trials,true,availableBytes);
    }
    private static Decision selectFrom(Key key,Config[] allowed,Candidate[] trials,boolean temporal,long availableBytes){
        if(trials==null||trials.length!=allowed.length)return unmeasured(key.cores,temporal);
        boolean[] seen=new boolean[allowed.length];Config best=null;int pairs=MAX_PAIRS,bestPairs=0;
        long baseMedian=0,candidateMedian=0,bestBase=0,bestCandidate=0;
        for(Candidate trial:trials){
            if(trial==null||trial.config==null)return unmeasured(key.cores,temporal);
            int index=index(allowed,trial.config);
            if(index<0||seen[index]||!validSamples(trial.samples,temporal))return unmeasured(key.cores,temporal);
            seen[index]=true;int count=trial.samples.length;pairs=Math.min(pairs,count);
            long[] baseline=new long[count],candidate=new long[count];boolean eligible=true;
            for(int i=0;i<count;i++){
                Sample sample=trial.samples[i];baseline[i]=sample.baselineNanos;candidate[i]=sample.candidateNanos;
                if(!sample.finite||!sample.exact||!atMost(sample.candidateNanos,sample.baselineNanos,95))eligible=false;
            }
            long bm=median(baseline),cm=median(candidate);baseMedian=bm;candidateMedian=cm;
            eligible&=atMost(cm,bm,90);
            if(eligible&&(best==null||(double)cm/bm<(double)bestCandidate/bestBase)){
                best=trial.config;bestPairs=count;bestBase=bm;bestCandidate=cm;
            }
        }
        return best==null?new Decision(baseline(key.cores),true,false,pairs,baseMedian,candidateMedian,"baseline-retained",temporal,availableBytes,trials):
                new Decision(best,true,true,bestPairs,bestBase,bestCandidate,"measured-improvement",temporal,availableBytes,trials);
    }
    private static boolean validSamples(Sample[] samples,boolean temporal){
        if(samples==null||samples.length<MIN_PAIRS||samples.length>MAX_PAIRS)return false;
        for(int i=0;i<samples.length;i++){
            Sample s=samples[i];if(s==null||s.baselineNanos<=0||s.candidateNanos<=0||s.baselineNanos>MAX_TRIAL_NANOS||s.candidateNanos>MAX_TRIAL_NANOS||s.temporalBands!=(temporal?TEMPORAL_BANDS:0))return false;
            if(i>0&&samples[i-1].candidateFirst==s.candidateFirst)return false;
        }
        return true;
    }
    private static boolean atMost(long candidate,long baseline,int percent){return candidate*100<=baseline*percent;}
    private static long median(long[] values){Arrays.sort(values);int middle=values.length/2;return values.length%2==1?values[middle]:values[middle-1]+(values[middle]-values[middle-1])/2;}
    private static int index(Config[] values,Config value){for(int i=0;i<values.length;i++)if(values[i].equals(value))return i;return -1;}
    private static boolean sameSet(Config[] expected,Config[] actual){
        if(actual==null||actual.length!=expected.length)return false;
        boolean[] seen=new boolean[expected.length];for(Config value:actual){int index=index(expected,value);if(index<0||seen[index])return false;seen[index]=true;}return true;
    }

    static Calibration load(File file,Key key){
        try{
            checkPath(file);if(!file.isFile()||file.length()>MAX_BYTES)return defaults(key);
            byte[] bytes=Files.readAllBytes(file.toPath());if(bytes.length<48||bytes.length>MAX_BYTES)return defaults(key);
            CRC32 crc=new CRC32();crc.update(bytes,8,bytes.length-8);DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes));
            if(in.readLong()!=crc.getValue()||in.readInt()!=MAGIC||in.readInt()!=SCHEMA)return defaults(key);
            byte[] digest=new byte[32];in.readFully(digest);if(!MessageDigest.isEqual(digest,key.fingerprint))return defaults(key);
            Calibration result=new Calibration(readDecision(in,key,true),readDecision(in,key,false));
            return in.read()==-1&&result.complete()?result:defaults(key);
        }catch(IOException|RuntimeException invalid){return defaults(key);}
    }
    static void save(File file,Key key,Calibration value)throws IOException {
        if(value==null||!value.complete())throw new IOException("Incomplete execution calibration cannot be saved.");
        validateDecision(value.temporal,key,true);validateDecision(value.frequency,key,false);
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);
        out.writeLong(0);out.writeInt(MAGIC);out.writeInt(SCHEMA);out.write(key.fingerprint);
        writeDecision(out,value.temporal);writeDecision(out,value.frequency);out.flush();byte[] payload=bytes.toByteArray();
        if(payload.length>=MAX_BYTES)throw new IOException("Execution calibration exceeded storage limit.");
        CRC32 crc=new CRC32();crc.update(payload,8,payload.length-8);long checksum=crc.getValue();for(int i=7;i>=0;i--){payload[i]=(byte)checksum;checksum>>>=8;}
        File parent=file.getAbsoluteFile().getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Execution calibration storage unavailable.");
        File temporary=new File(file.getPath()+".tmp");checkPath(file);checkPath(temporary);
        try{
            try(FileOutputStream stream=new FileOutputStream(temporary)){stream.write(payload);stream.getFD().sync();}
            Files.move(temporary.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
        }finally{Files.deleteIfExists(temporary.toPath());}
    }
    private static void checkPath(File file)throws IOException{if(Files.isSymbolicLink(file.toPath())||(file.exists()&&!file.isFile()))throw new IOException("Unexpected execution calibration entry.");}
    /** Retain bounded raw pair evidence rather than trusting only the winning median on reload. */
    private static void writeDecision(DataOutputStream out,Decision d)throws IOException{
        out.writeBoolean(d.temporalFamily);out.writeLong(d.availableBytes);out.writeInt(d.trials.length);
        for(Candidate trial:d.trials){
            Config c=trial.config;out.writeInt(c.intraThreads);out.writeInt(c.interThreads);out.writeInt(c.dynamicBlockBase);out.writeBoolean(c.parallel);out.writeInt(c.temporalWorkers);out.writeInt(c.timeBatch);
            out.writeInt(trial.samples.length);
            for(Sample s:trial.samples){out.writeLong(s.baselineNanos);out.writeLong(s.candidateNanos);out.writeBoolean(s.candidateFirst);out.writeBoolean(s.finite);out.writeBoolean(s.exact);out.writeInt(s.temporalBands);}
        }
    }
    private static Decision readDecision(DataInputStream in,Key key,boolean temporal)throws IOException{
        if(in.readBoolean()!=temporal)throw new IOException("Mismatched execution family.");
        long availableBytes=in.readLong();int count=in.readInt();
        Config[] expected=temporal?temporalCandidates(key,availableBytes):candidates(key.cores);
        if(temporal&&key.cores<4&&availableBytes==0&&count==0)return retainedTemporal(key);
        if((!temporal&&availableBytes!=0)||count==0||count!=expected.length)throw new IOException("Incomplete execution shortlist.");
        Candidate[] trials=new Candidate[count];
        for(int i=0;i<count;i++){
            Config config=new Config(in.readInt(),in.readInt(),in.readInt(),in.readBoolean(),in.readInt(),in.readInt());
            int pairCount=in.readInt();if(pairCount<MIN_PAIRS||pairCount>MAX_PAIRS)throw new IOException("Invalid execution pair count.");
            Sample[] samples=new Sample[pairCount];for(int j=0;j<pairCount;j++)samples[j]=new Sample(in.readLong(),in.readLong(),in.readBoolean(),in.readBoolean(),in.readBoolean(),in.readInt());
            trials[i]=new Candidate(config,samples);
        }
        Decision result=selectFrom(key,expected,trials,temporal,availableBytes);validateDecision(result,key,temporal);return result;
    }
    private static void validateDecision(Decision d,Key key,boolean temporal)throws IOException{
        if(d==null||!d.complete||d.temporalFamily!=temporal)throw new IOException("Invalid execution calibration evidence.");
        if(temporal&&key.cores<4&&d.availableBytes==0&&d.trials!=null&&d.trials.length==0&&!d.eligible&&d.pairCount==0&&d.baselineMedianNanos==0&&d.candidateMedianNanos==0&&d.config.equals(baseline(key.cores)))return;
        Config[] allowed=temporal?temporalCandidates(key,d.availableBytes):candidates(key.cores);
        Decision rebuilt=selectFrom(key,allowed,d.trials,temporal,d.availableBytes);
        if(allowed.length==0||!rebuilt.complete||!rebuilt.config.equals(d.config)||rebuilt.eligible!=d.eligible||rebuilt.pairCount!=d.pairCount||rebuilt.baselineMedianNanos!=d.baselineMedianNanos||rebuilt.candidateMedianNanos!=d.candidateMedianNanos||(!temporal&&d.availableBytes!=0))
            throw new IOException("Unapproved execution scheduling configuration.");
    }
}

package com.cyberbasslord.lightforge;

import java.lang.reflect.Method;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;

/**
 * Bounded, observational timing evidence for one native Deux passage.
 *
 * The collector deliberately has no compile-time Android dependency and never receives audio,
 * paths, job identifiers, exception text or model payloads. It records the fixed production
 * topology only: one summary, at most sixteen named stages, and at most the 27 Deux graphs.
 * Calling-thread and whole-process CPU time use their respective real runtime clocks;
 * process CPU includes other app threads and is not accelerator utilization. Missing
 * CPU/accelerator/cache telemetry is serialized as unavailable, never as a synthetic zero.
 */
final class NativeInferenceProfile {
    static final int MAX_GRAPH_RECORDS = 27;
    static final int MAX_STAGE_RECORDS = 16;
    static final int MAX_POLICY_RECORDS = 8, MAX_POLICY_RECORD_BYTES = 512;
    static final int MAX_RECORDS = 1 + MAX_STAGE_RECORDS + MAX_GRAPH_RECORDS + MAX_POLICY_RECORDS;
    private static final long NANOS_PER_MILLISECOND = 1000000L;
    private static final long UNSET = -1L;
    private static final CpuClock CPU_CLOCK = resolveCpuClock();
    private static final CpuClock PROCESS_CPU_CLOCK = processCpuClock();

    private final long startedNanos = System.nanoTime();
    private final LinkedHashMap<String, Stage> stages = new LinkedHashMap<String, Stage>();
    private final LinkedHashMap<String, Graph> graphs = new LinkedHashMap<String, Graph>();
    private final LinkedHashSet<String> rejectedGraphs = new LinkedHashSet<String>();
    private final Metric concurrentRuns = new Metric();
    private final Metric inferencePipelines = new Metric();
    private long finishedNanos = UNSET;
    private long directBufferBytes, schedulerCalibrationNanos;
    private int schedulerCalibrationCount;
    private String temporalConfig = "unavailable", frequencyConfig = "unavailable";
    private int temporalBaselineSessions, temporalFourWorkerSessions, temporalEightWorkerSessions, temporalUnobservedSessions;
    private int frequencyBaselineSessions, frequencyFourWorkerSessions, frequencyEightWorkerSessions, frequencyUnobservedSessions;
    private String[] passagePolicyRecords = new String[0];
    private long memoryStartUsed = UNSET, memoryStartLimit = UNSET, memoryEndUsed = UNSET, memoryEndLimit = UNSET;
    private long heapObservedPeak = UNSET;
    private int droppedGraphs, droppedStages, cacheHits, cacheMisses;
    private long cacheHitBytes, cacheMissBytes;
    private boolean cacheObserved, directBufferObserved, memoryUnavailable, cpuObserved, cpuUnavailable;
    private String outcome = "running";
    private Snapshot snapshot;
    private boolean candidateEvidenceRequested;
    private CandidateEvidence candidateEvidence;

    static Timing started() { return new Timing(System.nanoTime(), CPU_CLOCK.now(), PROCESS_CPU_CLOCK.now()); }
    static Measurement elapsed(Timing timing) {
        if (timing == null) return new Measurement(0L, UNSET);
        return new Measurement(Math.max(0L, System.nanoTime() - timing.wallStartedNanos), elapsedCpu(timing.cpuStartedNanos), elapsedProcessCpu(timing.processCpuStartedNanos));
    }
    static Measurement measurement(long wallNanos, long cpuNanos) { return new Measurement(Math.max(0L, wallNanos), cpuNanos < 0L ? UNSET : cpuNanos); }
    private static long elapsedCpu(long startedCpuNanos) {
        long now = CPU_CLOCK.now();
        return startedCpuNanos == UNSET || now == UNSET ? UNSET : Math.max(0L, now - startedCpuNanos);
    }

    private static long elapsedProcessCpu(long startedCpuNanos) {
        long now = PROCESS_CPU_CLOCK.now();
        return startedCpuNanos == UNSET || now == UNSET ? UNSET : Math.max(0L, now - startedCpuNanos);
    }

    synchronized void captureStartMemory() {
        if (memoryStartUsed != UNSET || memoryUnavailable) return;
        Heap heap = heap();
        if (heap == null) { memoryUnavailable = true; return; }
        memoryStartUsed = heap.used; memoryStartLimit = heap.limit; noteHeap(heap.used);
    }

    synchronized void addGateWait(long nanos) { addGateWait(measurement(nanos, UNSET)); }
    synchronized void addEngineInit(long nanos) { addEngineInit(measurement(nanos, UNSET)); }
    synchronized void addPreflight(long nanos) { addPreflight(measurement(nanos, UNSET)); }
    synchronized void addBufferInit(long nanos) { addBufferInit(measurement(nanos, UNSET)); }
    synchronized void addRuntimeInit(long nanos) { addRuntimeInit(measurement(nanos, UNSET)); }
    synchronized void addRead(long nanos) { addRead(measurement(nanos, UNSET)); }
    synchronized void addEncode(long nanos) { addEncode(measurement(nanos, UNSET)); }
    synchronized void addWrite(long nanos) { addWrite(measurement(nanos, UNSET)); }
    synchronized void addFlush(long nanos) { addFlush(measurement(nanos, UNSET)); }
    synchronized void addOutputCommit(long nanos) { addOutputCommit(measurement(nanos, UNSET)); }

    synchronized void addGateWait(Measurement timing) { stage("inference-gate-wait", timing); }
    synchronized void addEngineInit(Measurement timing) { stage("engine-init", timing); }
    synchronized void addPreflight(Measurement timing) { stage("cache-preflight", timing); }
    synchronized void addBufferInit(Measurement timing) { stage("buffer-init", timing); }
    synchronized void addRuntimeInit(Measurement timing) { stage("runtime-setup", timing); }
    synchronized void addRead(Measurement timing) { stage("pcm-read", timing); }
    synchronized void addEncode(Measurement timing) { stage("feature-encode", timing); }
    synchronized void addWrite(Measurement timing) { stage("output-write", timing); }
    synchronized void addFlush(Measurement timing) { stage("output-flush", timing); }
    synchronized void addOutputCommit(Measurement timing) { stage("output-commit", timing); }

    /** Fixed privacy-safe identity only; no dependency on the scheduler implementation. */
    synchronized void noteSchedulerConfiguration(String family, String config) {
        if (snapshot != null || config == null) return;
        boolean baseline = config.matches("cpu-i[1-6]-j1-d(?:0|4)-sequential");
        if ("temporal".equals(family) && (baseline || config.matches("cpu-i1-j1-d0-sequential-w(?:4|8)-b1"))) temporalConfig = config;
        else if ("frequency".equals(family) && (baseline || config.matches("cpu-i1-j1-d0-sequential-w(?:4|8)-b16"))) frequencyConfig = config;
    }

    /** Diagnostic opt-in only. Auxiliary observations never enter production records or totals. */
    synchronized void enableCandidateEvidence() { if (snapshot == null) candidateEvidenceRequested = true; }
    synchronized boolean wantsCandidateEvidence() { return candidateEvidenceRequested && snapshot == null; }
    synchronized void noteCandidateEvidence(CandidateEvidence evidence) {
        if (candidateEvidenceRequested && snapshot == null && candidateEvidence == null) candidateEvidence = evidence;
    }
    synchronized CandidateEvidence candidateEvidence() { return candidateEvidence; }

    /** Extra scheduler probes are observational overhead, never production graph runs/stages. */
    synchronized void noteSchedulerCalibration(long wallNanos) {
        if (snapshot != null) return;
        schedulerCalibrationNanos += Math.max(0L, wallNanos); schedulerCalibrationCount++;
    }

    /** Retain the controller's complete, bounded evidence snapshot; never arbitrary log text. */
    synchronized void notePassagePolicy(String[] evidenceRecords) {
        if (snapshot != null || evidenceRecords == null) return;
        String[] accepted = validatedPassagePolicy(evidenceRecords);
        if (accepted != null) passagePolicyRecords = accepted;
    }

    private static final String POLICY_REASONS = "(?:unmeasured|fresh-pair-required|nominated|initial-pair|qualification-wait|qualification-pair|slow-passage-recheck|lease-recheck|qualified-lease|measured-passage-improvement|qualification-pending|invalid-nomination|unfinished-pair|invalid-plan|memory-ineligible|short-job|probe-budget|missed-qualification|payback-unavailable|short-renewal|invalid-pair|pair-regression|invalid-pair-order|median-regression|invalid-timing|probe-aborted|external-baseline|cancelled|memory-fallback|thermal-guard|output-mismatch|memory-pressure|screen-budget|screen-no-win|runtime-rejected|unknown-work|control-required|slow-passage-control|control-accepted|control-regression|control-incomplete|unfinished-control)";
    private static final String POLICY_HEADER = "schema=native-passage-policy-v1 state=(?:baseline|qualified|provisional) workers=(?:0|4|8) reason=" + POLICY_REASONS +
        " extraNanos=[0-9]{1,19} extraCapNanos=360000000000 projectedAccruedSavingsNanos=[0-9]{1,19} qualificationPairs=[0-3] currentJobPairs=[0-9]{1,4} seeded=(?:true|false) activePassages=[0-9]{1,4} leasePassages=(?:8|12) paybackScope=projected-not-measured";
    private static final String POLICY_PAIR = "schema=native-passage-pair-v1 role=(?:qualification|recheck) index=[0-2] ordinal=[0-9]{1,4} candidateFirst=(?:true|false) workers=(?:4|8) baselineNanos=[0-9]{1,19} candidateNanos=[0-9]{1,19} extraNanos=[0-9]{1,19} outputSha256=[a-f0-9]{64} finite=(?:true|false) exact=(?:true|false) fullGeometry=(?:true|false) coldSessions=(?:true|false)";
    private static final String POLICY_CONTROL = "schema=native-passage-control-v1 ordinal=[0-9]{1,4} baselineNanos=[0-9]{1,19} previousBaselineNanos=[0-9]{1,19} candidateMaxNanos=[0-9]{1,19} candidateSamples=3 accepted=(?:true|false) comparisonScope=unmatched-inputs";

    /** Delimiters cannot occur in validated tokens. The durable summary needs no extra callback. */
    static String encodePassagePolicy(String[] records) {
        StringBuilder encoded = new StringBuilder();
        for (String record : records) {
            if (encoded.length() != 0) encoded.append('|');
            encoded.append(record.replace(' ', ','));
        }
        return encoded.toString();
    }

    static String[] decodePassagePolicy(String encoded) {
        if (encoded == null || encoded.length() > MAX_POLICY_RECORDS * (MAX_POLICY_RECORD_BYTES + 1)) return null;
        if (encoded.isEmpty()) return new String[0];
        String[] records = encoded.split("\\|", -1);
        for (int i = 0; i < records.length; i++) records[i] = records[i].replace(',', ' ');
        return validatedPassagePolicy(records);
    }

    private static String[] validatedPassagePolicy(String[] records) {
        if (records.length > MAX_POLICY_RECORDS) return null;
        if (records.length == 0) return new String[0];
        int qualification = 0, rechecks = 0, controls = 0;
        for (int i = 0; i < records.length; i++) {
            String record = records[i];
            if (record == null || record.length() > MAX_POLICY_RECORD_BYTES) return null;
            boolean control = i > 0 && record.matches(POLICY_CONTROL);
            if (!(control || record.matches(i == 0 ? POLICY_HEADER : POLICY_PAIR))) return null;
            for (String token : record.split(" ")) {
                int equal = token.indexOf('='); String key = token.substring(0, equal), value = token.substring(equal + 1);
                if (!"outputSha256".equals(key) && value.matches("[0-9]+")) {
                    try {
                        long number = Long.parseLong(value);
                        if (("ordinal".equals(key) && number > 4095) ||
                            (("currentJobPairs".equals(key) || "activePassages".equals(key)) && number > 4096)) return null;
                        if (control && ("baselineNanos".equals(key) || "previousBaselineNanos".equals(key) || "candidateMaxNanos".equals(key)) &&
                            (number < 1 || number > 3600000000000L)) return null;
                    } catch (NumberFormatException invalid) { return null; }
                }
            }
            if (i > 0) {
                if (control) { if (++controls > 1) return null; continue; }
                if (controls != 0) return null;
                if (record.contains(" role=qualification ")) {
                    if (rechecks != 0 || qualification >= 3 || !record.contains(" index=" + qualification + " ")) return null;
                    qualification++;
                } else if (++rechecks > 1 || !record.contains(" index=0 ")) return null;
            }
        }
        if (!records[0].contains(" qualificationPairs=" + qualification + " ")) return null;
        return records.clone();
    }

    synchronized void noteDirectBufferBytes(long bytes) { directBufferObserved = true; directBufferBytes = Math.max(directBufferBytes, nonnegative(bytes)); }
    synchronized void noteCacheModelHit(long bytes) { cacheObserved = true; cacheHits++; cacheHitBytes += nonnegative(bytes); }
    synchronized void noteCacheModelMiss(long bytes) { cacheObserved = true; cacheMisses++; cacheMissBytes += nonnegative(bytes); }

    synchronized void addModelPrepare(String graph, long nanos) { addModelPrepare(graph, measurement(nanos, UNSET)); }
    synchronized void addSessionInit(String graph, long nanos) { addSessionInit(graph, measurement(nanos, UNSET)); }
    synchronized void addTensorBind(String graph, long nanos) { addTensorBind(graph, measurement(nanos, UNSET)); }
    synchronized void addRun(String graph, long nanos) { addRun(graph, measurement(nanos, UNSET)); }
    synchronized void addPack(String graph, long nanos) { addPack(graph, measurement(nanos, UNSET)); }
    synchronized void addScatter(String graph, long nanos) { addScatter(graph, measurement(nanos, UNSET)); }
    synchronized void addDecode(String graph, long nanos) { addDecode(graph, measurement(nanos, UNSET)); }

    synchronized void addModelPrepare(String graph, Measurement timing) { Graph item = graph(graph); if (item != null) item.modelPrepare.add(timing); stage("model-init", timing); }
    synchronized void addSessionInit(String graph, Measurement timing) {
        if (snapshot != null) return;
        Graph item = graph(graph);
        if (item != null) {
            item.sessionInit.add(timing);
            if (graph.matches("block-(?:0[0-9]|1[01])-time")) {
                if ("cpu-i1-j1-d0-sequential-w4-b1".equals(temporalConfig)) temporalFourWorkerSessions++;
                else if ("cpu-i1-j1-d0-sequential-w8-b1".equals(temporalConfig)) temporalEightWorkerSessions++;
                else if (!"unavailable".equals(temporalConfig)) temporalBaselineSessions++;
                else temporalUnobservedSessions++;
            } else if (graph.matches("block-(?:0[0-9]|1[01])-frequency")) {
                if ("cpu-i1-j1-d0-sequential-w4-b16".equals(frequencyConfig)) frequencyFourWorkerSessions++;
                else if ("cpu-i1-j1-d0-sequential-w8-b16".equals(frequencyConfig)) frequencyEightWorkerSessions++;
                else if (!"unavailable".equals(frequencyConfig)) frequencyBaselineSessions++;
                else frequencyUnobservedSessions++;
            }
        }
        stage("model-init", timing);
    }
    synchronized void addTensorBind(String graph, Measurement timing) { Graph item = graph(graph); if (item != null) item.tensorBind.add(timing); stage("tensor-bind", timing); }
    synchronized void addRun(String graph, Measurement timing) { Graph item = graph(graph); if (item != null) item.run.add(timing); stage("inference", timing); }
    /**
     * One actual concurrent Run, measured on its worker. These call intervals overlap:
     * their wall time is an aggregate graph cost, and their process CPU must not be summed.
     * The coordinator records a nonoverlapping parent interval with addInferenceWave
     * or addInferencePipeline.
     */
    synchronized void addConcurrentRun(String graph, Measurement timing) {
        Graph item = graph(graph);
        if (item == null) return;
        Measurement worker = new Measurement(timing.wallNanos, timing.cpuNanos, UNSET);
        item.concurrent = true; item.run.add(worker); concurrentRuns.add(worker);
    }
    /** One coordinator interval, after every worker in this wave has retired. */
    synchronized void addInferenceWave(Measurement timing) { stage("inference", timing); }
    /**
     * One whole temporal pipeline, including initial packing, refill/scatter and worker
     * retirement. Reusable tensors must be bound before this interval starts. Nested
     * copies remain visible, but their caller CPU is deducted from the stage CPU sum.
     */
    synchronized void addInferencePipeline(Measurement timing) {
        if (snapshot != null) return;
        inferencePipelines.add(timing); stage("inference", timing);
    }
    synchronized void addPipelinePack(String graph, Measurement timing) { pipelineCopy(graph, timing, true); }
    synchronized void addPipelineScatter(String graph, Measurement timing) { pipelineCopy(graph, timing, false); }
    synchronized void addPack(String graph, Measurement timing) { Graph item = graph(graph); if (item != null) item.pack.add(timing); stage("pack", timing); }
    synchronized void addScatter(String graph, Measurement timing) { Graph item = graph(graph); if (item != null) item.scatter.add(timing); stage("scatter", timing); }
    synchronized void addDecode(String graph, Measurement timing) { Graph item = graph(graph); if (item != null) item.decode.add(timing); stage("decode", timing); }

    private void pipelineCopy(String name, Measurement timing, boolean packing) {
        if (snapshot != null) return;
        // Other native workers run during these copies. Their process CPU overlaps
        // the parent interval and cannot be attributed to copying or summed again.
        Measurement nested = new Measurement(timing.wallNanos, timing.cpuNanos, UNSET);
        Graph item = graph(name);
        if (item != null) (packing ? item.pack : item.scatter).add(nested, true);
        stage(packing ? "pack" : "scatter", nested, true);
    }

    /** Idempotent so failure/cancellation cleanup cannot mutate an already completed receipt. */
    synchronized Snapshot finish(String requestedOutcome) {
        if (snapshot != null) return snapshot;
        outcome = safeOutcome(requestedOutcome);
        finishedNanos = System.nanoTime();
        Heap heap = heap();
        if (heap == null) memoryUnavailable = true;
        else { memoryEndUsed = heap.used; memoryEndLimit = heap.limit; noteHeap(heap.used); }
        String[] records = new String[1 + stages.size() + graphs.size() + passagePolicyRecords.length];
        records[0] = summaryRecord();
        int index = 1;
        for (Stage stage : stages.values()) records[index++] = stageRecord(stage);
        for (Graph graph : graphs.values()) records[index++] = graphRecord(graph);
        for (String policy : passagePolicyRecords) records[index++] = policy;
        snapshot = new Snapshot(records);
        return snapshot;
    }

    private void stage(String name, Measurement timing) { stage(name, timing, false); }
    private void stage(String name, Measurement timing, boolean nested) {
        if (snapshot != null) return;
        Stage item = stages.get(name);
        if (item == null) {
            if (name == null || !name.matches("[a-z0-9-]{1,40}") || stages.size() >= MAX_STAGE_RECORDS) { droppedStages++; return; }
            item = new Stage(name); stages.put(name, item);
        }
        item.add(timing, nested); noteCpu(timing);
        // One bounded heap observation per named stage avoids turning high-frequency graph batches
        // into allocator probes while still exposing stage-adjacent memory pressure.
        if (item.heapObserved == UNSET && !memoryUnavailable) {
            Heap heap = heap();
            if (heap == null) memoryUnavailable = true;
            else { item.heapObserved = heap.used; noteHeap(heap.used); }
        }
    }

    private Graph graph(String name) {
        if (snapshot != null) return null;
        if (name == null || !name.matches("[a-z0-9-]{1,40}")) { noteRejected(name); return null; }
        Graph existing = graphs.get(name);
        if (existing != null) return existing;
        if (graphs.size() >= MAX_GRAPH_RECORDS) { noteRejected(name); return null; }
        Graph created = new Graph(name);
        if (!memoryUnavailable) {
            Heap heap = heap();
            if (heap == null) memoryUnavailable = true;
            else { created.heapObserved = heap.used; noteHeap(heap.used); }
        }
        graphs.put(name, created); return created;
    }

    private void noteRejected(String name) {
        String key = name == null || !name.matches("[a-z0-9-]{1,40}") ? "invalid" : name;
        if (rejectedGraphs.size() < MAX_GRAPH_RECORDS && rejectedGraphs.add(key)) droppedGraphs++;
    }
    private void noteCpu(Measurement timing) { if (timing.cpuNanos == UNSET) cpuUnavailable = true; else cpuObserved = true; }
    private void noteHeap(long used) { heapObservedPeak = heapObservedPeak == UNSET ? used : Math.max(heapObservedPeak, used); }

    private String summaryRecord() {
        Stage preprocess = combined("preprocess", "pcm-read", "feature-encode");
        Stage postprocess = combined("postprocess", "decode", "output-write", "output-flush", "output-commit");
        Stage modelInit = stages.get("model-init"), inference = stages.get("inference"), wait = stages.get("inference-gate-wait");
        Stage engineInit = stages.get("engine-init"), preflight = stages.get("cache-preflight");
        Stage bufferInit = stages.get("buffer-init"), runtimeInit = stages.get("runtime-setup");
        return "schema=native-inference-profile-v2" +
            " outcome=" + outcome +
            " wallMs=" + milliseconds(finishedNanos - startedNanos) +
            " temporalConfig=" + temporalConfig + " frequencyConfig=" + frequencyConfig +
            " temporalConfigCountScope=session-init-attempts" +
            " temporalBaselineSessionCount=" + temporalBaselineSessions +
            " temporalFourWorkerSessionCount=" + temporalFourWorkerSessions +
            " temporalEightWorkerSessionCount=" + temporalEightWorkerSessions +
            " temporalUnobservedSessionCount=" + temporalUnobservedSessions +
            " frequencyConfigCountScope=session-init-attempts" +
            " frequencyBaselineSessionCount=" + frequencyBaselineSessions +
            " frequencyFourWorkerSessionCount=" + frequencyFourWorkerSessions +
            " frequencyEightWorkerSessionCount=" + frequencyEightWorkerSessions +
            " frequencyUnobservedSessionCount=" + frequencyUnobservedSessions +
            " schedulerCalibrationWallMs=" + valueOrUnavailable(schedulerCalibrationNanos, schedulerCalibrationCount == 0) +
            " schedulerCalibrationCount=" + countOrUnavailable(schedulerCalibrationCount, schedulerCalibrationCount == 0) +
            " cpuScope=calling-thread processCpuScope=all-app-threads" +
            " cpuTelemetry=" + telemetry(cpuObserved, cpuUnavailable) +
            " instrumentedCpuMs=" + instrumentedCpu() + " instrumentedCpuScope=nonoverlapping-calling-thread" +
            " memoryTelemetry=" + (memoryUnavailable ? "unavailable" : "java-heap") +
            " acceleratorTelemetry=unavailable" +
            " waitWallMs=" + wall(wait) + " waitCpuMs=" + cpu(wait) +
            " engineInitWallMs=" + wall(engineInit) +
            " preflightWallMs=" + wall(preflight) +
            " bufferInitWallMs=" + wall(bufferInit) +
            " runtimeInitWallMs=" + wall(runtimeInit) +
            " preprocessWallMs=" + wall(preprocess) + " preprocessCpuMs=" + cpu(preprocess) +
            " modelInitWallMs=" + wall(modelInit) + " modelInitCpuMs=" + cpu(modelInit) +
            " inferenceWallMs=" + wall(inference) + " inferenceCpuMs=" + cpu(inference) +
            " inferenceThreadCpuMs=" + cpu(inference) + " inferenceProcessCpuMs=" + processCpu(inference) +
            " inferenceWallScope=critical-path inferenceThreadCpuScope=" + (concurrentRuns.count == 0 && inferencePipelines.count == 0 ? "calling-thread" : "coordinator") +
            " inferenceWorkScope=" + inferenceWorkScope() +
            " inferenceWorkerThreadCpuScope=sum-run-calling-threads" +
            " inferenceWorkerThreadCpuMs=" + valueOrUnavailable(concurrentRuns.cpuNanos, concurrentRuns.cpuUnavailable || !concurrentRuns.cpuObserved) +
            " inferenceWorkerCpuTelemetry=" + telemetry(concurrentRuns.cpuObserved, concurrentRuns.cpuUnavailable) +
            " inferenceWorkerRunCount=" + concurrentRuns.count +
            " inferenceCount=" + inferenceCount() + " sessionInitCount=" + sessionInitCount() +
            " postprocessWallMs=" + wall(postprocess) + " postprocessCpuMs=" + cpu(postprocess) +
            " directBufferTelemetry=" + (directBufferObserved ? "observed" : "unavailable") +
            " directBufferBytes=" + bytesOrUnavailable(directBufferBytes, !directBufferObserved) +
            " heapStartUsedBytes=" + bytesOrUnavailable(memoryStartUsed, memoryStartUsed == UNSET) +
            " heapStartLimitBytes=" + bytesOrUnavailable(memoryStartLimit, memoryStartLimit == UNSET) +
            " heapEndUsedBytes=" + bytesOrUnavailable(memoryEndUsed, memoryEndUsed == UNSET) +
            " heapEndLimitBytes=" + bytesOrUnavailable(memoryEndLimit, memoryEndLimit == UNSET) +
            " heapObservedPeakBytes=" + bytesOrUnavailable(heapObservedPeak, heapObservedPeak == UNSET) +
            " cacheTelemetry=" + (cacheObserved ? "observed" : "unavailable") +
            " cacheModelHits=" + countOrUnavailable(cacheHits, !cacheObserved) +
            " cacheModelMisses=" + countOrUnavailable(cacheMisses, !cacheObserved) +
            " cacheHitBytes=" + bytesOrUnavailable(cacheHitBytes, !cacheObserved) +
            " cacheMissBytes=" + bytesOrUnavailable(cacheMissBytes, !cacheObserved) +
            " stageRecords=" + stages.size() + " graphRecords=" + graphs.size() +
            " droppedStageRecords=" + droppedStages + " droppedGraphRecords=" + droppedGraphs +
            (passagePolicyRecords.length == 0 ? "" : " passagePolicy=" + encodePassagePolicy(passagePolicyRecords));
    }

    private int sessionInitCount() { int count = 0; for (Graph graph : graphs.values()) count += graph.sessionInit.count; return count; }
    private int inferenceCount() { int count = 0; for (Graph graph : graphs.values()) count += graph.run.count; return count; }
    private String inferenceWorkScope() { return inferencePipelines.count == 0 ? "run-and-wave-coordination" : "run-and-pipeline-coordination"; }
    private String instrumentedCpu() {
        if (!cpuObserved || anyCpuUnavailable(stages.values())) return "unavailable";
        long nestedCpu = 0L; int nestedCount = 0;
        for (Stage stage : stages.values()) { nestedCpu += stage.nestedCpuNanos; nestedCount += stage.nestedCount; }
        // Missing parents and impossible nesting are invalid observations, not zero CPU.
        if (nestedCount > 0 && (inferencePipelines.count == 0 || !inferencePipelines.cpuObserved ||
                inferencePipelines.cpuUnavailable || nestedCpu > inferencePipelines.cpuNanos)) return "unavailable";
        long total = sumCpu(stages.values());
        return nestedCpu > total ? "unavailable" : String.valueOf(milliseconds(total - nestedCpu));
    }
    private static String processCpu(Metric metric) {
        return metric == null ? "unavailable" : valueOrUnavailable(metric.processCpuNanos, metric.processCpuUnavailable || !metric.processCpuObserved);
    }

    private String stageRecord(Stage stage) {
        return "schema=native-inference-stage-v1" +
            " stage=" + stage.name + " samples=" + stage.samples +
            " wallScope=" + ("inference".equals(stage.name) ? "critical-path" : intervalScope(stage)) +
            ("inference".equals(stage.name) ? " workScope=" + inferenceWorkScope() : "") +
            " cpuScope=calling-thread processCpuScope=" + (stage.nestedCount == 0 ? "all-app-threads" : "unavailable-overlapping-intervals") +
            " processCpuMs=" + processCpu(stage) +
            " wallMs=" + milliseconds(stage.wallNanos) +
            " cpuTelemetry=" + telemetry(stage.cpuObserved, stage.cpuUnavailable) +
            " cpuMs=" + valueOrUnavailable(stage.cpuNanos, stage.cpuUnavailable || !stage.cpuObserved) +
            " heapTelemetry=" + (stage.heapObserved == UNSET ? "unavailable" : "java-heap") +
            " heapObservedBytes=" + bytesOrUnavailable(stage.heapObserved, stage.heapObserved == UNSET);
    }

    private static String graphRecord(Graph graph) {
        return "schema=native-inference-graph-v2" +
            " graph=" + graph.name +
            " graphWallScope=" + (graph.concurrent ? "aggregate-call" : "sequential-intervals") +
            " runCpuScope=" + (graph.concurrent ? "run-calling-threads" : "calling-thread") +
            " runProcessCpuScope=" + (graph.concurrent ? "unavailable-overlapping-intervals" : "all-app-threads") +
            " packWallScope=" + intervalScope(graph.pack) + " scatterWallScope=" + intervalScope(graph.scatter) +
            " packProcessCpuScope=" + copyProcessCpuScope(graph.pack) + " scatterProcessCpuScope=" + copyProcessCpuScope(graph.scatter) +
            " cpuTelemetry=" + telemetry(graph.cpuObserved(), graph.cpuUnavailable()) +
            " heapTelemetry=" + (graph.heapObserved == UNSET ? "unavailable" : "java-heap") +
            " heapObservedBytes=" + bytesOrUnavailable(graph.heapObserved, graph.heapObserved == UNSET) +
            metric("modelPrepare", graph.modelPrepare) + metric("sessionInit", graph.sessionInit) +
            metric("tensorBind", graph.tensorBind) + metric("run", graph.run) +
            metric("pack", graph.pack) + metric("scatter", graph.scatter) + metric("decode", graph.decode);
    }

    private static String metric(String name, Metric value) {
        return " " + name + "Count=" + value.count + " " + name + "WallMs=" + wall(value) +
            " " + name + "CpuMs=" + valueOrUnavailable(value.cpuNanos, value.cpuUnavailable || !value.cpuObserved) +
            " " + name + "ProcessCpuMs=" + processCpu(value);
    }
    private static String intervalScope(Metric value) {
        return value.count == 0 ? "unavailable" : value.nestedCount == 0 ? "sequential-intervals" :
            value.nestedCount == value.count ? "nested-in-inference-pipeline" : "mixed-nested-and-sequential-intervals";
    }
    private static String copyProcessCpuScope(Metric value) {
        return value.count == 0 ? "unavailable" : value.nestedCount == 0 ? "all-app-threads" : "unavailable-overlapping-intervals";
    }
    private Stage combined(String name, String... names) {
        Stage result = null;
        for (String item : names) {
            Stage stage = stages.get(item);
            if (stage != null) {
                if (result == null) result = new Stage(name);
                result.merge(stage);
            }
        }
        return result;
    }
    private static String wall(Stage stage) { return stage == null ? "unavailable" : String.valueOf(milliseconds(stage.wallNanos)); }
    private static String wall(Metric metric) { return metric.count == 0 ? "unavailable" : String.valueOf(milliseconds(metric.wallNanos)); }
    private static String cpu(Stage stage) { return stage == null ? "unavailable" : valueOrUnavailable(stage.cpuNanos, stage.cpuUnavailable || !stage.cpuObserved); }
    private static long sumCpu(Iterable<Stage> values) { long total = 0L; for (Stage value : values) total += value.cpuNanos; return total; }
    private static boolean anyCpuUnavailable(Iterable<Stage> values) { for (Stage value : values) if (value.cpuUnavailable || !value.cpuObserved) return true; return false; }
    private static long nonnegative(long value) { return Math.max(0L, value); }
    private static long milliseconds(long nanos) { return nonnegative(nanos) / NANOS_PER_MILLISECOND; }
    private static String valueOrUnavailable(long nanos, boolean unavailable) { return unavailable ? "unavailable" : String.valueOf(milliseconds(nanos)); }
    private static String bytesOrUnavailable(long value, boolean unavailable) { return unavailable ? "unavailable" : String.valueOf(value); }
    private static String countOrUnavailable(int value, boolean unavailable) { return unavailable ? "unavailable" : String.valueOf(value); }
    private static String telemetry(boolean available, boolean unavailable) { return !available ? "unavailable" : unavailable ? "partial" : "available"; }
    private static String safeOutcome(String value) { return value != null && value.matches("(?:completed|failed|cancelled|released)") ? value : "unknown"; }

    static final class Timing {
        final long wallStartedNanos, cpuStartedNanos, processCpuStartedNanos;
        Timing(long wallStartedNanos, long cpuStartedNanos, long processCpuStartedNanos) { this.wallStartedNanos = wallStartedNanos; this.cpuStartedNanos = cpuStartedNanos; this.processCpuStartedNanos = processCpuStartedNanos; }
    }
    static final class Measurement {
        final long wallNanos, cpuNanos, processCpuNanos;
        Measurement(long wallNanos, long cpuNanos) { this(wallNanos, cpuNanos, UNSET); }
        Measurement(long wallNanos, long cpuNanos, long processCpuNanos) { this.wallNanos = nonnegative(wallNanos); this.cpuNanos = cpuNanos < 0L ? UNSET : cpuNanos; this.processCpuNanos = processCpuNanos < 0L ? UNSET : processCpuNanos; }
    }
    static final class Snapshot {
        private final String[] records;
        Snapshot(String[] records) { this.records = records.clone(); }
        int recordCount() { return records.length; }
        String record(int index) { return records[index]; }
        String[] records() { return records.clone(); }
    }
    /** Cumulative direct model-I/O observations; reads include interrupted attempts. */
    static final class ModelSetup {
        final int verifiedModels;
        final long extractionAttempts, extractionBytesRead, existingFileChecksumAttempts, existingFileChecksumBytesRead;
        ModelSetup(int verified, long extractions, long extractedBytes, long checksums, long checksumBytes) {
            if (verified < 0 || verified > MAX_GRAPH_RECORDS || extractions < 0 || extractedBytes < 0 || checksums < 0 || checksumBytes < 0)
                throw new IllegalArgumentException("Invalid model setup observation");
            verifiedModels = verified; extractionAttempts = extractions; extractionBytesRead = extractedBytes;
            existingFileChecksumAttempts = checksums; existingFileChecksumBytesRead = checksumBytes;
        }
    }
    static final class ArmEvidence {
        final String outcome;
        final long armWallNanos;
        final ModelSetup before, after;
        ArmEvidence(String outcome, long nanos, ModelSetup before, ModelSetup after) {
            if (!("completed".equals(outcome) || "cancelled".equals(outcome) || "failed".equals(outcome)) ||
                ("completed".equals(outcome) ? nanos <= 0 : nanos != -1) || before == null || after == null ||
                after.extractionAttempts < before.extractionAttempts || after.extractionBytesRead < before.extractionBytesRead ||
                after.existingFileChecksumAttempts < before.existingFileChecksumAttempts || after.existingFileChecksumBytesRead < before.existingFileChecksumBytesRead)
                throw new IllegalArgumentException("Invalid paired arm observation");
            this.outcome = outcome; armWallNanos = nanos; this.before = before; this.after = after;
        }
    }
    static final class CandidateEvidence {
        final int ordinal, workers, commonPreflightVerifiedModelCount;
        final boolean candidateFirst;
        final ArmEvidence baseline, candidate;
        final Snapshot profile;
        CandidateEvidence(int ordinal, int workers, boolean first, int commonVerified, ArmEvidence baseline,
                ArmEvidence candidate, Snapshot profile) {
            if (ordinal < 0 || ordinal > 4095 || (workers != 4 && workers != 8) || commonVerified < 0 || commonVerified > MAX_GRAPH_RECORDS ||
                candidate == null || profile == null || profile.recordCount() < 1 || profile.recordCount() > MAX_RECORDS)
                throw new IllegalArgumentException("Invalid candidate evidence");
            this.ordinal = ordinal; this.workers = workers; candidateFirst = first;
            commonPreflightVerifiedModelCount = commonVerified; this.baseline = baseline; this.candidate = candidate; this.profile = profile;
        }
    }
    private static class Metric {
        long wallNanos, cpuNanos, processCpuNanos, nestedCpuNanos; int count, nestedCount; boolean cpuObserved, cpuUnavailable, processCpuObserved, processCpuUnavailable;
        void add(Measurement timing) { add(timing, false); }
        void add(Measurement timing, boolean nested) {
            wallNanos += timing.wallNanos; count++;
            if (nested) { nestedCount++; if (timing.cpuNanos != UNSET) nestedCpuNanos += timing.cpuNanos; }
            if (timing.cpuNanos == UNSET) cpuUnavailable = true; else { cpuObserved = true; cpuNanos += timing.cpuNanos; }
            if (timing.processCpuNanos == UNSET) processCpuUnavailable = true; else { processCpuObserved = true; processCpuNanos += timing.processCpuNanos; }
        }
    }
    private static final class Stage extends Metric {
        final String name; long heapObserved = UNSET; int samples;
        Stage(String name) { this.name = name; }
        @Override void add(Measurement timing, boolean nested) { super.add(timing, nested); samples++; }
        void merge(Stage other) { wallNanos += other.wallNanos; cpuNanos += other.cpuNanos; count += other.count; samples += other.samples; nestedCount += other.nestedCount; nestedCpuNanos += other.nestedCpuNanos; cpuObserved |= other.cpuObserved; cpuUnavailable |= other.cpuUnavailable; processCpuNanos += other.processCpuNanos; processCpuObserved |= other.processCpuObserved; processCpuUnavailable |= other.processCpuUnavailable; heapObserved = heapObserved == UNSET ? other.heapObserved : other.heapObserved == UNSET ? heapObserved : Math.max(heapObserved, other.heapObserved); }
    }
    private static final class Graph {
        final String name; long heapObserved = UNSET; boolean concurrent;
        final Metric modelPrepare = new Metric(), sessionInit = new Metric(), tensorBind = new Metric(), run = new Metric(), pack = new Metric(), scatter = new Metric(), decode = new Metric();
        Graph(String name) { this.name = name; }
        boolean cpuObserved() { return modelPrepare.cpuObserved || sessionInit.cpuObserved || tensorBind.cpuObserved || run.cpuObserved || pack.cpuObserved || scatter.cpuObserved || decode.cpuObserved; }
        boolean cpuUnavailable() { return modelPrepare.cpuUnavailable || sessionInit.cpuUnavailable || tensorBind.cpuUnavailable || run.cpuUnavailable || pack.cpuUnavailable || scatter.cpuUnavailable || decode.cpuUnavailable; }
    }
    private static final class Heap { final long used, limit; Heap(long used, long limit) { this.used = used; this.limit = limit; } }
    private Heap heap() {
        try { Runtime runtime = Runtime.getRuntime(); return new Heap(Math.max(0L, runtime.totalMemory() - runtime.freeMemory()), Math.max(0L, runtime.maxMemory())); }
        catch (Throwable ignored) { return null; }
    }
    private interface CpuClock { long now(); }
    private static CpuClock resolveCpuClock() {
        final CpuClock android = androidCpuClock();
        final CpuClock host = hostCpuClock();
        return new CpuClock() { @Override public long now() {
            long value = android.now(); return value == UNSET ? host.now() : value;
        }};
    }
    private static CpuClock processCpuClock() {
        final CpuClock android = androidProcessCpuClock();
        // Android stub jars may expose this method but throw when invoked on a host JVM.
        // Choose a working real clock once so an interval never mixes different clock sources.
        return android.now() != UNSET ? android : hostProcessCpuClock();
    }
    private static CpuClock androidProcessCpuClock() {
        final Method android = staticMethod("android.os.Process", "getElapsedCpuTime");
        if (android != null) return new CpuClock() { @Override public long now() {
            long milliseconds = invokeLong(android, null);
            return milliseconds < 0 || milliseconds > Long.MAX_VALUE / NANOS_PER_MILLISECOND ? UNSET : milliseconds * NANOS_PER_MILLISECOND;
        }};
        return unavailableCpuClock();
    }
    private static CpuClock hostProcessCpuClock() {
        // Host profiling uses the real process clock when exported by the operating-system bean.
        try {
            Object bean = Class.forName("java.lang.management.ManagementFactory").getMethod("getOperatingSystemMXBean").invoke(null);
            final Object operatingSystem = bean;
            final Method processTime = Class.forName("com.sun.management.OperatingSystemMXBean").getMethod("getProcessCpuTime");
            return new CpuClock() { @Override public long now() { return invokeLong(processTime, operatingSystem); } };
        } catch (Throwable ignored) { return unavailableCpuClock(); }
    }

    private static CpuClock androidCpuClock() {
        final Method android = staticMethod("android.os.Debug", "threadCpuTimeNanos");
        if (android != null) return new CpuClock() { @Override public long now() { return invokeLong(android, null); } };
        return unavailableCpuClock();
    }
    private static CpuClock hostCpuClock() {
        try {
            Class<?> management = Class.forName("java.lang.management.ManagementFactory");
            final Object bean = management.getMethod("getThreadMXBean").invoke(null);
            Class<?> type = Class.forName("java.lang.management.ThreadMXBean");
            Object supported = type.getMethod("isCurrentThreadCpuTimeSupported").invoke(bean);
            if (!Boolean.TRUE.equals(supported)) return unavailableCpuClock();
            Method enabled = type.getMethod("isThreadCpuTimeEnabled");
            // Observation must not modify a process-wide JVM switch. If the host disables this
            // clock, report it as unavailable rather than changing inference conditions.
            if (!Boolean.TRUE.equals(enabled.invoke(bean))) return unavailableCpuClock();
            final Method current = type.getMethod("getCurrentThreadCpuTime");
            return new CpuClock() { @Override public long now() { return invokeLong(current, bean); } };
        } catch (Throwable ignored) { return unavailableCpuClock(); }
    }
    private static Method staticMethod(String className, String name) {
        try { return Class.forName(className).getMethod(name); } catch (Throwable ignored) { return null; }
    }
    private static long invokeLong(Method method, Object receiver) {
        try { Object value = method.invoke(receiver); return value instanceof Long && ((Long)value).longValue() >= 0L ? ((Long)value).longValue() : UNSET; }
        catch (Throwable ignored) { return UNSET; }
    }
    private static CpuClock unavailableCpuClock() { return new CpuClock() { @Override public long now() { return UNSET; } }; }
}

package com.cyberbasslord.lightforge;

import java.io.*;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.Arrays;
import java.util.zip.CRC32;

/** Pure, bounded admission for a complete-passage CPU schedule; never executes inference. */
final class NativePassagePolicy {
    static final long EXTRA_CAP_NANOS=360000000000L;
    static final long FOUR_WORKER_HEADROOM=1536L*1024*1024, EIGHT_WORKER_HEADROOM=2048L*1024*1024;
    static final int MAX_BYTES=16384, MAX_PASSAGES=4096;
    private static final long MAX_PASSAGE_NANOS=3600000000000L;
    private static final int MAGIC=0x4c465050, SCHEMA=2;
    enum Action { BASELINE, PAIR, CANDIDATE, CONTROL }

    static final class Plan {
        final Action action;
        final int workers;
        final boolean candidateFirst;
        final long probeBudgetNanos;
        final String reason;
        private Plan(Action action,int workers,boolean first,long budget,String reason){
            this.action=action;this.workers=workers;candidateFirst=first;probeBudgetNanos=budget;this.reason=reason;
        }
    }

    static final class Pair {
        final int ordinal,candidateWorkers;
        final boolean candidateFirst,finite,exact,fullGeometry,coldSessions;
        final long baselineNanos,candidateNanos,extraNanos;
        final String outputSha256;
        Pair(int ordinal,boolean candidateFirst,long baselineNanos,long candidateNanos,long extraNanos,
                String outputSha256,boolean finite,boolean exact,boolean fullGeometry,boolean coldSessions,int candidateWorkers){
            this.ordinal=ordinal;this.candidateFirst=candidateFirst;this.baselineNanos=baselineNanos;
            this.candidateNanos=candidateNanos;this.extraNanos=extraNanos;this.outputSha256=outputSha256;
            this.finite=finite;this.exact=exact;this.fullGeometry=fullGeometry;this.coldSessions=coldSessions;
            this.candidateWorkers=candidateWorkers;
        }
    }

    /** Only a reconstructed, complete qualification can create a seed. */
    static final class Seed {
        final int workers;
        private final String identity;
        private final Pair[] qualification;
        private final Pair recheck;
        private Seed(String identity,int workers,Pair[] qualification,Pair recheck){
            this.identity=identity;this.workers=workers;this.qualification=qualification.clone();this.recheck=recheck;
        }
    }
    private static final class Control {
        final int ordinal;
        final long baselineNanos,previousBaselineNanos,candidateMaxNanos;
        final boolean accepted;
        Control(int ordinal,long baseline,long previous,long candidate,boolean accepted){
            this.ordinal=ordinal;baselineNanos=baseline;previousBaselineNanos=previous;candidateMaxNanos=candidate;this.accepted=accepted;
        }
    }

    private final String identity;
    private final Pair[] qualification=new Pair[3];
    private final long[] recent=new long[3];
    private int workers,qualificationCount,lastOrdinal=-1,activePassages,lease=8,recentCount,pairCount,controlRemaining;
    private long extraNanos,projectedAccruedSavingsNanos,baselineBracket;
    private long projectedSavingLimit=Long.MAX_VALUE;
    private boolean seeded,freshRequired,qualified,latched,pending,controlPending,slow;
    private Pair recheck;
    private Control control;
    private Seed retainedSeed;
    private Plan previous;
    private String reason="unmeasured";

    NativePassagePolicy(String identity,Seed seed){
        if(!digest(identity))throw new IllegalArgumentException("Invalid passage policy identity.");
        this.identity=identity;
        if(seed!=null&&identity.equals(seed.identity)&&validSeed(seed)){
            workers=seed.workers;System.arraycopy(seed.qualification,0,qualification,0,3);qualificationCount=3;
            recheck=seed.recheck;seeded=true;freshRequired=true;reason="fresh-pair-required";
            retainedSeed=seed;
        }
    }

    /** Screening nominates one schedule and consumes budget; it cannot qualify a schedule. */
    void nominate(int workers,long screeningNanos){
        addExtra(screeningNanos);
        if(latched)return;
        if(!workerCount(workers)||qualificationCount!=0||pending||lastOrdinal>=0||this.workers!=0){
            forceBaseline("invalid-nomination");return;
        }
        this.workers=workers;reason="nominated";
    }

    /** remainingUseful includes this passage; -1 means unknown and never permits a probe. */
    Plan plan(int ordinal,int remainingUseful,long headroom,int cores){
        if(pending||controlPending){forceBaseline(controlPending?"unfinished-control":"unfinished-pair");return baseline();}
        if(ordinal<0||ordinal>=MAX_PASSAGES||ordinal<=lastOrdinal||remainingUseful< -1||remainingUseful>MAX_PASSAGES){
            forceBaseline("invalid-plan");return baseline();
        }
        lastOrdinal=ordinal;
        if(latched)return baseline();
        if(remainingUseful== -1){forceBaseline("unknown-work");return baseline();}
        if(workers==0){reason="unmeasured";return baseline();}
        if(!allowed(workers,headroom,cores)){forceBaseline("memory-ineligible");return baseline();}
        if(!qualified){
            if(freshRequired){
                if(remainingUseful<8){forceBaseline("short-job");return baseline();}
                if(!canFundProbe()){forceBaseline("probe-budget");return baseline();}
                if(!payback(remainingUseful-1,3,lastOrdinal,estimatedExtra())){
                    forceBaseline("payback-unavailable");return baseline();
                }
                return pair(recheck==null?!qualification[2].candidateFirst:!recheck.candidateFirst,"fresh-pair-required");
            }
            if(qualificationCount==0){
                if(ordinal!=0||remainingUseful<24){forceBaseline("short-job");return baseline();}
                return pair(false,"initial-pair");
            }
            int due=qualificationCount;
            if(ordinal<due){reason="qualification-wait";return baseline();}
            if(ordinal!=due){forceBaseline("missed-qualification");return baseline();}
            if(!payback(remainingUseful,qualificationCount,lastOrdinal-1)||!canFundProbe()){
                forceBaseline("payback-unavailable");return baseline();
            }
            return pair((qualificationCount&1)!=0,"qualification-pair");
        }
        boolean renewal=slow||activePassages>=lease;
        if(renewal){
            if(remainingUseful<4){forceBaseline("short-renewal");return baseline();}
            // This is a useful baseline passage, not another candidate replay.
            // Its output advances the song; only its foregone acceleration enters payback.
            if(!payback(remainingUseful-1,3,lastOrdinal,0,true)){forceBaseline("payback-unavailable");return baseline();}
            reason=slow?"slow-passage-control":"control-required";controlPending=true;
            controlRemaining=remainingUseful-1;
            previous=new Plan(Action.CONTROL,0,false,0,reason);return previous;
        }
        reason="qualified-lease";
        previous=new Plan(Action.CANDIDATE,workers,false,0,reason);return previous;
    }

    /** remainingUseful counts useful passages AFTER this completed paired passage. */
    void recordPair(Pair pair,int remainingUseful){
        if(pair!=null)addExtra(pair.extraNanos);
        boolean expected=pending&&previous!=null&&pair!=null&&pair.ordinal==lastOrdinal
            &&pair.candidateWorkers==workers&&pair.candidateFirst==previous.candidateFirst;
        pending=false;
        if(latched)return;
        if(!expected||remainingUseful<0||remainingUseful>MAX_PASSAGES||!validPair(pair,workers)){
            if(expected&&recordable(pair,workers))recheck=pair;
            forceBaseline("invalid-pair");return;
        }
        pairCount++;
        if(!faster(pair,95)){recheck=pair;forceBaseline("pair-regression");return;}
        boolean newLease=!qualified;
        if(freshRequired){
            recheck=pair;freshRequired=false;qualified=true;
        }else if(!qualified){
            if(pair.ordinal!=qualificationCount||pair.candidateFirst!=((qualificationCount&1)!=0)){
                forceBaseline("invalid-pair-order");return;
            }
            qualification[qualificationCount++]=pair;
            if(qualificationCount==3){
                if(!qualifiedMedians(qualification)){forceBaseline("median-regression");return;}
                qualified=true;
            }
        }else recheck=pair;
        lease=newLease?8:12;
        if(qualified){
            baselineBracket=minBaseline();
            Seed seed=new Seed(identity,workers,qualification,recheck);
            if(validSeed(seed))retainedSeed=seed;
        }
        if(!payback(remainingUseful,qualificationCount,pair.ordinal)){
            forceBaseline("payback-unavailable");return;
        }
        activePassages=0;recentCount=0;slow=false;
        reason=qualified?"measured-passage-improvement":"qualification-pending";
    }

    /** Observe the selected ordinary path only; its duration is not a paired speedup measurement. */
    void recordOrdinary(long wallNanos){
        if(pending||controlPending){forceBaseline(controlPending?"unfinished-control":"unfinished-pair");return;}
        if(!timing(wallNanos)){forceBaseline("invalid-timing");return;}
        if(latched||previous==null||previous.action!=Action.CANDIDATE)return;
        activePassages++;
        long projectedBaseline=Math.min(minBaseline(),baselineBracket);
        long projected=Math.max(0,Math.min(minSaving(),projectedBaseline-wallNanos));
        projectedAccruedSavingsNanos+=projected;
        recent[recentCount%3]=wallNanos;recentCount++;
        if(recentCount>=3){
            long reference=candidateMedian();int slower=0;
            for(long value:recent)if(value*100>reference*125)slower++;
            slow=slower>=2;
        }
        previous=null;
    }

    /** A useful baseline output is a conservative timing control, never a same-input comparison. */
    void recordControl(long wallNanos){
        boolean expected=controlPending&&previous!=null&&previous.action==Action.CONTROL;
        controlPending=false;
        if(latched)return;
        if(!expected||!timing(wallNanos)||recentCount<3||!timing(baselineBracket)){
            forceBaseline("control-incomplete");return;
        }
        long candidate=0;for(long duration:recent)candidate=Math.max(candidate,duration);
        long reference=Math.min(baselineBracket,wallNanos);
        boolean accepted=candidate*100<=reference*95;
        control=new Control(lastOrdinal,wallNanos,baselineBracket,candidate,accepted);
        if(!accepted){forceBaseline("control-regression");return;}
        // This unmatched observation only lowers a projection; it never establishes matched speed proof.
        projectedSavingLimit=Math.min(projectedSavingLimit,Math.max(0,reference-candidate));
        baselineBracket=wallNanos;
        if(!payback(controlRemaining,3,lastOrdinal,0,true)){forceBaseline("payback-unavailable");return;}
        activePassages=0;recentCount=0;slow=false;lease=12;previous=null;
        reason="control-accepted";
    }

    /** Caller reports completed extra work after retiring native resources at a safe checkpoint. */
    void probeAborted(String reason,long extraNanos){
        addExtra(extraNanos);pending=false;forceBaseline(safeReason(reason,"probe-aborted"));
    }

    void forceBaseline(String reason){
        String safe=safeReason(reason,"external-baseline");
        if(!retainsEvidence(safe))retainedSeed=null;
        if(!latched)this.reason=safe;
        latched=true;qualified=false;pending=false;controlPending=false;previous=null;
    }

    /** Retained complete evidence is not permission to execute a candidate in the current job. */
    Seed qualifiedSeed(){
        return retainedSeed!=null&&validSeed(retainedSeed)?retainedSeed:null;
    }

    String[] evidenceRecords(){
        String[] records=new String[1+qualificationCount+(recheck==null?0:1)+(control==null?0:1)];
        records[0]="schema=native-passage-policy-v1 state="+(latched?"baseline":qualified?"qualified":"provisional")
            +" workers="+workers+" reason="+reason+" extraNanos="+extraNanos+" extraCapNanos="+EXTRA_CAP_NANOS
            +" projectedAccruedSavingsNanos="+projectedAccruedSavingsNanos
            +" qualificationPairs="+qualificationCount+" currentJobPairs="+pairCount+" seeded="+seeded
            +" activePassages="+activePassages+" leasePassages="+lease+" paybackScope=projected-not-measured";
        for(int i=0;i<qualificationCount;i++)records[i+1]=record("qualification",i,qualification[i]);
        int next=qualificationCount+1;
        if(recheck!=null)records[next++]=record("recheck",0,recheck);
        if(control!=null)records[next]="schema=native-passage-control-v1 ordinal="+control.ordinal
            +" baselineNanos="+control.baselineNanos+" previousBaselineNanos="+control.previousBaselineNanos
            +" candidateMaxNanos="+control.candidateMaxNanos+" candidateSamples=3 accepted="+control.accepted+" comparisonScope=unmatched-inputs";
        return records;
    }

    private Plan baseline(){previous=new Plan(Action.BASELINE,0,false,0,reason);return previous;}
    private Plan pair(boolean first,String reason){
        if(extraNanos>=EXTRA_CAP_NANOS){forceBaseline("probe-budget");return baseline();}
        this.reason=reason;pending=true;
        previous=new Plan(Action.PAIR,workers,first,EXTRA_CAP_NANOS-extraNanos,reason);return previous;
    }
    private void addExtra(long value){
        if(value<0){forceBaseline("invalid-timing");return;}
        extraNanos=value>Long.MAX_VALUE-extraNanos?Long.MAX_VALUE:extraNanos+value;
        if(extraNanos>EXTRA_CAP_NANOS)forceBaseline("probe-budget");
    }
    private boolean canFundProbe(){long extra=estimatedExtra();return extra>0&&extraNanos<=EXTRA_CAP_NANOS-extra;}

    /** Conservative projection. Its bounded lease horizon never spends unavailable future probe budget. */
    private boolean payback(int remaining,int measured,int ordinal){
        return payback(remaining,measured,ordinal,0);
    }
    private boolean payback(int remaining,int measured,int ordinal,long immediateExtra){
        return payback(remaining,measured,ordinal,immediateExtra,false);
    }
    private boolean payback(int remaining,int measured,int ordinal,long immediateExtra,boolean renewedControl){
        if(remaining<=0||measured<=0)return false;
        long baseline=maxBaseline(),saving=Math.min(minSaving(),projectedSavingLimit);
        if(recentCount>=3){
            long candidate=0;for(long duration:recent)candidate=Math.max(candidate,duration);
            saving=Math.min(saving,Math.max(0,Math.min(minBaseline(),baselineBracket)-candidate));
        }
        if(baseline<=0||saving<=0)return false;
        int needed=3-measured;
        long probeCost=estimatedExtra(),futureQualification=needed*probeCost;
        if(immediateExtra>EXTRA_CAP_NANOS-extraNanos||futureQualification>EXTRA_CAP_NANOS-extraNanos-immediateExtra)return false;
        int waiting=needed;
        int available=Math.max(0,remaining-waiting);
        if(available==0)return false;
        long committed=extraNanos+futureQualification+immediateExtra;
        int firstLease=renewedControl?12:qualified?lease:8;
        int useful=Math.min(available,firstLease),left=available-useful;
        while(left>=4){
            left--; // One useful baseline control advances the song without earning candidate acceleration.
            int accelerated=Math.min(left,12);useful+=accelerated;left-=accelerated;
        }
        long costs=committed;
        long margin=(remaining*baseline+9)/10;
        // Bounds on remaining and passage clocks make every product here fit in signed long.
        return projectedAccruedSavingsNanos+useful*saving>=costs+margin;
    }
    private long maxBaseline(){
        long value=0;for(int i=0;i<qualificationCount;i++)value=Math.max(value,qualification[i].baselineNanos);
        if(recheck!=null&&validPair(recheck,workers))value=Math.max(value,recheck.baselineNanos);return value;
    }
    private long minBaseline(){
        long value=Long.MAX_VALUE;for(int i=0;i<qualificationCount;i++)value=Math.min(value,qualification[i].baselineNanos);
        if(recheck!=null&&validPair(recheck,workers))value=Math.min(value,recheck.baselineNanos);
        return value==Long.MAX_VALUE?0:value;
    }
    /** Baseline is useful output during a comparison; candidate replay and its validation are extra. */
    private long estimatedExtra(){
        long candidate=0,observed=0;
        for(int i=0;i<qualificationCount;i++){
            candidate=Math.max(candidate,qualification[i].candidateNanos);observed=Math.max(observed,qualification[i].extraNanos);
        }
        if(recheck!=null&&validPair(recheck,workers)){
            candidate=Math.max(candidate,recheck.candidateNanos);observed=Math.max(observed,recheck.extraNanos);
        }
        return Math.max(observed,(candidate*110+99)/100);
    }
    private long minSaving(){
        long value=Long.MAX_VALUE;
        for(int i=0;i<qualificationCount;i++)value=Math.min(value,qualification[i].baselineNanos-qualification[i].candidateNanos);
        if(recheck!=null&&validPair(recheck,workers))value=Math.min(value,recheck.baselineNanos-recheck.candidateNanos);
        return value==Long.MAX_VALUE?0:value;
    }
    private long candidateMedian(){
        if(recheck!=null)return recheck.candidateNanos;
        long[] values=new long[qualificationCount];for(int i=0;i<values.length;i++)values[i]=qualification[i].candidateNanos;
        return median(values);
    }
    private static boolean timing(long value){return value>0&&value<=MAX_PASSAGE_NANOS;}
    private static boolean workerCount(int workers){return workers==4||workers==8;}
    private static boolean allowed(int workers,long memory,int cores){return cores>=workers&&memory>=(workers==8?EIGHT_WORKER_HEADROOM:FOUR_WORKER_HEADROOM);}
    private static boolean digest(String value){return value!=null&&value.matches("[0-9a-f]{64}");}
    private static boolean validPair(Pair p,int workers){
        return recordable(p,workers)&&p.finite&&p.exact&&p.fullGeometry&&p.coldSessions;
    }
    private static boolean recordable(Pair p,int workers){
        return p!=null&&p.ordinal>=0&&p.ordinal<MAX_PASSAGES&&workerCount(workers)&&p.candidateWorkers==workers
            &&timing(p.baselineNanos)&&timing(p.candidateNanos)&&p.extraNanos>=Math.min(p.baselineNanos,p.candidateNanos)
            &&p.extraNanos<=EXTRA_CAP_NANOS&&digest(p.outputSha256);
    }
    private static boolean faster(Pair pair,int percent){return pair.candidateNanos*100<=pair.baselineNanos*percent;}
    private static boolean qualifiedMedians(Pair[] pairs){
        long[] baseline=new long[3],candidate=new long[3];
        for(int i=0;i<3;i++){baseline[i]=pairs[i].baselineNanos;candidate[i]=pairs[i].candidateNanos;}
        return median(candidate)*100<=median(baseline)*85;
    }
    private static long median(long[] values){if(values.length==0)return 0;Arrays.sort(values);return values[values.length/2];}
    private static boolean validSeed(Seed seed){
        if(seed==null||!digest(seed.identity)||!workerCount(seed.workers)||seed.qualification.length!=3)return false;
        long qualificationExtra=0;
        for(int i=0;i<3;i++){
            Pair p=seed.qualification[i];
            if(!validPair(p,seed.workers)||p.ordinal!=i||p.candidateFirst!=((i&1)!=0)||!faster(p,95))return false;
            qualificationExtra+=p.extraNanos;
        }
        // All three qualification pairs belong to one job. A later cached-job recheck does not.
        if(qualificationExtra>EXTRA_CAP_NANOS)return false;
        return qualifiedMedians(seed.qualification)&&(seed.recheck==null||(validPair(seed.recheck,seed.workers)&&faster(seed.recheck,95)));
    }
    private static String safeReason(String value,String fallback){
        if(value==null)return fallback;
        switch(value){
            case "invalid-nomination":case "unfinished-pair":case "invalid-plan":case "memory-ineligible":
            case "short-job":case "probe-budget":case "missed-qualification":case "payback-unavailable":
            case "short-renewal":case "invalid-pair":case "pair-regression":case "invalid-pair-order":
            case "median-regression":case "invalid-timing":case "probe-aborted":case "external-baseline":
            case "cancelled":case "memory-fallback":case "thermal-guard":case "output-mismatch":
            case "memory-pressure":case "screen-budget":case "screen-no-win":
            case "runtime-rejected":case "unknown-work":
            case "control-required":case "slow-passage-control":case "control-accepted":case "control-regression":
            case "control-incomplete":case "unfinished-control":
                return value;
            default:return fallback;
        }
    }
    private static boolean retainsEvidence(String reason){
        return "short-job".equals(reason)||"short-renewal".equals(reason)||"unknown-work".equals(reason)
            ||"payback-unavailable".equals(reason)||"probe-budget".equals(reason);
    }
    private static String record(String role,int index,Pair p){
        return "schema=native-passage-pair-v1 role="+role+" index="+index+" ordinal="+p.ordinal
            +" candidateFirst="+p.candidateFirst+" workers="+p.candidateWorkers+" baselineNanos="+p.baselineNanos
            +" candidateNanos="+p.candidateNanos+" extraNanos="+p.extraNanos+" outputSha256="+p.outputSha256
            +" finite="+p.finite+" exact="+p.exact+" fullGeometry="+p.fullGeometry+" coldSessions="+p.coldSessions;
    }

    static Seed load(File file,String identity){
        if(!digest(identity))return null;
        try{
            checkPath(file);if(!file.isFile()||file.length()>MAX_BYTES)return null;
            ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[1024];
            try(InputStream in=new FileInputStream(file)){
                int count;while((count=in.read(buffer))!=-1){if(bytes.size()+count>MAX_BYTES)return null;bytes.write(buffer,0,count);}
            }
            byte[] payload=bytes.toByteArray();if(payload.length<64)return null;
            CRC32 crc=new CRC32();crc.update(payload,8,payload.length-8);
            DataInputStream in=new DataInputStream(new ByteArrayInputStream(payload));
            if(in.readLong()!=crc.getValue()||in.readInt()!=MAGIC||in.readInt()!=SCHEMA)return null;
            String stored=in.readUTF();if(!identity.equals(stored))return null;
            int workers=in.readInt(),count=in.readInt();if(count!=3)return null;
            Pair[] pairs=new Pair[3];for(int i=0;i<3;i++)pairs[i]=readPair(in);
            Pair recheck=in.readBoolean()?readPair(in):null;
            if(in.read()!=-1)return null;
            Seed seed=new Seed(identity,workers,pairs,recheck);return validSeed(seed)?seed:null;
        }catch(IOException|RuntimeException invalid){return null;}
    }
    static void save(File file,String identity,Seed seed)throws IOException{
        if(!digest(identity)||!validSeed(seed)||!identity.equals(seed.identity))throw new IOException("Unqualified passage policy cannot be saved.");
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);
        out.writeLong(0);out.writeInt(MAGIC);out.writeInt(SCHEMA);out.writeUTF(identity);out.writeInt(seed.workers);out.writeInt(3);
        for(Pair pair:seed.qualification)writePair(out,pair);
        out.writeBoolean(seed.recheck!=null);if(seed.recheck!=null)writePair(out,seed.recheck);out.flush();
        byte[] payload=bytes.toByteArray();if(payload.length>MAX_BYTES)throw new IOException("Passage policy exceeds its storage limit.");
        CRC32 crc=new CRC32();crc.update(payload,8,payload.length-8);long checksum=crc.getValue();
        for(int i=7;i>=0;i--){payload[i]=(byte)checksum;checksum>>>=8;}
        File parent=file.getAbsoluteFile().getParentFile();
        if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Passage policy storage unavailable.");
        File temporary=new File(file.getPath()+".tmp");checkPath(file);checkPath(temporary);
        try{
            try(FileOutputStream stream=new FileOutputStream(temporary)){stream.write(payload);stream.getFD().sync();}
            Files.move(temporary.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
        }finally{Files.deleteIfExists(temporary.toPath());}
    }
    private static void checkPath(File file)throws IOException{
        if(Files.isSymbolicLink(file.toPath())||(file.exists()&&!file.isFile()))throw new IOException("Unexpected passage policy entry.");
    }
    private static void writePair(DataOutputStream out,Pair p)throws IOException{
        out.writeInt(p.ordinal);out.writeBoolean(p.candidateFirst);out.writeLong(p.baselineNanos);out.writeLong(p.candidateNanos);
        out.writeLong(p.extraNanos);out.writeUTF(p.outputSha256);out.writeBoolean(p.finite);out.writeBoolean(p.exact);
        out.writeBoolean(p.fullGeometry);out.writeBoolean(p.coldSessions);out.writeInt(p.candidateWorkers);
    }
    private static Pair readPair(DataInputStream in)throws IOException{
        return new Pair(in.readInt(),in.readBoolean(),in.readLong(),in.readLong(),in.readLong(),in.readUTF(),
            in.readBoolean(),in.readBoolean(),in.readBoolean(),in.readBoolean(),in.readInt());
    }
}

